		Cwd:                  flags.cwd,
		DefaultLibraryPath:   defaultLibraryPath,
		Callbacks:            callbacksList,
		Async:                flags.async,
		CollectTiming:        flags.timing,
		RunExternalCode:      flags.runExternalCode,
		ContentMapperSpawner: newSystem(),
