import { API, JsxEmit, ModuleKind, ModuleResolutionKind } from 'typescript/unstable/async';
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { performance } from 'node:perf_hooks';
import { resolve } from 'node:path';
const cwd = resolve('.');
const opts = { strict: true, jsx: JsxEmit.ReactJSX, module: ModuleKind.ESNext, moduleResolution: ModuleResolutionKind.Bundler, skipLibCheck: true, noEmit: true };
const ms = n => n.toFixed(1)+'ms';
const file = resolve('fixture/src/Mui.tsx'); const text = readFileSync(file,'utf8');
for (let round=0; round<3; round++) {
  const t0 = performance.now();
  const api = new API({ cwd, collectTiming: true });
  const snap = await api.createSnapshot({ createPrograms: [{ rootFiles: [file], compilerOptions: opts }] });
  const ck = snap.getProject(snap.operation.createdPrograms[0].id).checker;
  const tInit = performance.now();
  const ty = await ck.getTypeAtPosition(file, text.indexOf('MuiButtonProps')+1);
  const tFirst = performance.now();
  let reqs = 0;
  const props = await ck.getPropertiesOfType(ty); reqs++;
  const ptypes = await ck.getTypeOfSymbol(props); reqs++;
  const strs = [];
  for (const pt of ptypes) { strs.push(await ck.typeToString(pt)); reqs++; }
  const tWalk = performance.now();
  if (round===0) {
    const names = props.map(p=>p.name);
    const i = names.indexOf('sx'), v = names.indexOf('variant'), c = names.indexOf('color');
    console.log('type:', (await ck.typeToString(ty)).slice(0,120));
    console.log('props:', props.length, ' sx:', strs[i]?.slice(0,140), '\n variant:', strs[v]?.slice(0,120), '\n color:', strs[c]?.slice(0,120));
  }
  let rss='?'; try { rss = (parseInt(execSync("ps -o rss= -p $(pgrep -f 'api --async' | head -1)").toString())/1024).toFixed(0)+'MB'; } catch {}
  console.log(`round ${round}: spawn+snapshot ${ms(tInit-t0)} | first query (project load+check) ${ms(tFirst-tInit)} | walk ${props.length} props / ${reqs} reqs ${ms(tWalk-tFirst)} | tsc server RSS ${rss}`);
  const ti = await api.getTimingInfo(); if (round===2) console.log('timing:', JSON.stringify(ti.totals));
  await api.close();
}
EOF
