    for comp in sorted(a["components"]):
        pa, pb = a["components"][comp]["props"], b["components"][comp]["props"]
        if sorted(pa) != sorted(pb): print("  PROP SET CHANGED", comp, sorted(set(pa) ^ set(pb)))
        for name in sorted(pa):
            if name in pb and pa[name] != pb[name]:
                fields = [k for k in pa[name] if pa[name][k] != pb[name].get(k)]
                pt = lambda p: (p.get("parent") or {}).get("name")
