fn main() -> Result<()> {
    let cli = Cli::parse();

    init_tracing(cli.verbose);

    let exit_code = match cli.command {
        Command::Extract(args) => cmd_extract(args, cli.quiet, cli.config.as_deref())?,
        Command::Watch(args) => cmd_watch(args, cli.quiet, cli.config.as_deref())?,
        Command::Check(args) => cmd_check(args, cli.quiet, cli.config.as_deref())?,
        Command::Inspect(args) => cmd_inspect(args, cli.config.as_deref())?,
        Command::Schema => {
            cmd_schema()?;
            0
        }
        Command::Lsp => {
            cmd_lsp()?;
            0
        }
        Command::Completions(args) => {
            cmd_completions(args)?;
            0
        }
    };

    if exit_code != 0 {
        std::process::exit(exit_code);
    }
    Ok(())
}

fn init_tracing(verbose: u8) {
    if verbose == 0 {
        return;
    }
    use tracing_subscriber::{fmt, EnvFilter};
    let filter = match verbose {
        1 => "info",
        2 => "debug",
        _ => "trace",
    };
    // stderr, never stdout: `lsp` reserves stdout exclusively for
    // Content-Length-framed protocol messages — any other byte written there
    // (a tracing::error!/warn! call firing mid-session) corrupts the
    // transport and desyncs a real editor's LSP client. stderr is safe for
    // every command, so this isn't LSP-specific special-casing.
    fmt().with_env_filter(EnvFilter::new(filter)).with_writer(std::io::stderr).init();
}

