    fn start_session_runs_the_first_extraction_quiet_or_not() {
        for quiet in [true, false] {
            let src = TempDir::new().unwrap();
            std::fs::write(src.path().join("Widget.tsx"), WIDGET).unwrap();
            let dir = src.path().to_str().unwrap().to_owned();
