        miette::miette!(
            "Component '{}' not found.\nAvailable: {}",
            args.component,
            output.components.keys().cloned().collect::<Vec<_>>().join(", ")
        )
    })?;

    print_component(component);
    Ok(output.exit_code(false))
}

