s += '''
/// Kills the child on drop so a failing assertion never leaks a watcher.
struct KillOnDrop(Child);

impl Drop for KillOnDrop {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

#[test]
fn watch_rewrites_out_with_the_new_props_when_a_source_file_changes() {
    let src = widget_dir();
    let scratch = TempDir::new().unwrap();
    let out = scratch.path().join("out.json");
    let _watcher = KillOnDrop(
        Command::new(env!("CARGO_BIN_EXE_oxc-react-docgen"))
            .args(["--quiet", "watch", "--src", src.path().to_str().unwrap(), "--out", out.to_str().unwrap()])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("failed to spawn the real binary"),
    );

    // An edit made before the watcher is listening is lost, so keep editing until `--out` appears.
    let widget = src.path().join("Widget.tsx");
    let deadline = Instant::now() + Duration::from_secs(30);
    let written: serde_json::Value = loop {
        std::fs::write(&widget, "export function Widget(props: { label: string; size: number }) { return null; }\\n")
            .unwrap();
        std::thread::sleep(Duration::from_millis(300));
        if let Ok(json) = std::fs::read_to_string(&out) {
            break serde_json::from_str(&json).unwrap();
        }
        assert!(Instant::now() < deadline, "watch never wrote --out");
    };

    let props: Vec<&String> = written["components"]["Widget"]["props"].as_object().unwrap().keys().collect();
    assert_eq!(props, ["label", "size"]);
}
'''
open(p, 'w').write(s)
EOF
